-- Preserve historical unbound v3 conversations; bind new v3 conversations to projects.
ALTER TABLE agent_conversations DROP CHECK ck_agent_conversations_scope, ADD CONSTRAINT ck_agent_conversations_scope CHECK ((scope_version = 3 AND stage IS NULL AND subject_type IS NULL AND subject_id IS NULL AND task_type IS NULL) OR (scope_version = 2 AND project_id IS NOT NULL AND stage IS NULL AND subject_type IS NULL AND subject_id IS NULL AND task_type IS NULL) OR (scope_version = 0 AND project_id IS NOT NULL AND stage IS NULL AND subject_type IS NULL AND subject_id IS NULL AND task_type IS NULL) OR (scope_version = 1 AND project_id IS NOT NULL AND stage IS NOT NULL AND subject_type IS NOT NULL AND subject_id IS NOT NULL AND subject_id > 0 AND task_type IS NOT NULL AND ((stage = 'source' AND subject_type = 'project' AND subject_id = project_id AND task_type = 'writing') OR (stage = 'assets' AND subject_type = 'project' AND subject_id = project_id AND task_type IN ('extraction','batch')) OR (stage = 'assets' AND subject_type = 'asset' AND task_type IN ('creation','image')) OR (stage = 'storyboard' AND subject_type = 'project' AND subject_id = project_id AND task_type IN ('planning','batch')) OR (stage = 'storyboard' AND subject_type = 'shot' AND task_type IN ('creation','image','video')))));
